			url: finacus_ajax_obj.ajaxurl,
			data: {
				'action': 'finacus_careers_position_ajax_request',
				'get_position_id' : get_position_id
			},
			success:function(data) {
				if(data != 0 ){
					$('.ajax-data').html(data);
					//$('#productPopup').modal('slide');
				}
				else{
					alert('no data found');
				}
				console.log(data);
			},
			error: function(errorThrown){
				console.log(errorThrown);
			}
		});
	});
});

