(function ($) {
gsap.registerPlugin(ScrollTrigger)
document.addEventListener("DOMContentLoaded", (event) => {
/* Same height div start function */
function setSameHeight(selector) {
    const elements = document.querySelectorAll(selector);
    if (!elements.length) return;

    // Reset height first (important for recalculating on resize)
    elements.forEach(el => el.style.height = 'auto');

    let maxHeight = 0;

    elements.forEach(el => {
        maxHeight = Math.max(maxHeight, el.offsetHeight);
    });

    elements.forEach(el => {
        el.style.height = maxHeight + 'px';
    });
}

function applySameHeights() {
    setSameHeight('.sameheight');    
}

// Run on load and resize
window.addEventListener('load', applySameHeights);
window.addEventListener('resize', applySameHeights);

/* Same height div end function */
    /*wow animation start*/
    var wow = new WOW(
        {
            boxClass: 'wow',      // default
            animateClass: 'animated', // default
            offset: 100,          // default
            mobile: false,       // default
        }
    )
    wow.init();
    /*wow animation end*/
